import json,pathlib,subprocess,re,collections
root=pathlib.Path.cwd();folder=root/'review/compiler/loom-r-hidden-boundaries-ac-m';oldtip='8c931b22c50f29466da3a1cbe3036784c9b447cf';base=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()
results=json.loads((folder/'results.json').read_text());mutants=json.loads((folder/'mutants-results.json').read_text())
def events(label):
 rows=[]
 for line in (folder/(label+'.log')).read_text().splitlines():
  try:e=json.loads(line)
  except ValueError:continue
  if isinstance(e,dict):rows.append(e)
 return rows
retry=events('cmd-adamic-shared-cache');guard=events('reader-guard')
assert any(e.get('Action')=='pass' and not e.get('Test') for e in retry)
assert any(e.get('Action')=='pass' and e.get('Test')=='TestCallTargetReaders' for e in guard)
assert len(mutants)==42 and all(r['caught'] for r in mutants)
contaminants=[]
for r in mutants:
 text=(folder/(r['label']+'.log')).read_text()
 if re.search(r'\[-Werror|undefined reference|fatal error:|\[build failed\]|panic: test timed out|main\.c:\d+.*error:',text):contaminants.append(r['label'])
assert not contaminants,contaminants
alltests=[dict(package=e.get('Package'),name=e['Test'],action=e['Action'],seconds=e.get('Elapsed',0)) for e in retry+guard if e.get('Test') and e.get('Action') in ('pass','fail','skip')]
for r in results:
 if r['label']!='cmd-adamic':alltests.extend(r['tests'])
touched={}
for p in subprocess.check_output(['git','diff','--name-only',oldtip+'^',oldtip,'--','*_test.go'],text=True).splitlines():
 for name in re.findall(r'^func (Test\w+)\(t \*testing.T\)',(root/p).read_text(),re.M):touched[(str(pathlib.Path(p).parent),name)]=p
owned=[t for t in alltests if (str(t['package']).removeprefix('github.com/system-inc/adamic/'),t['name'].split('/')[0]) in touched]
assert all(t['seconds']<60 for t in owned)
(folder/'touched-test-grain.json').write_text(json.dumps(dict(scope='All tests in every Go test file the source commit adds or modifies, including unchanged functions in those files',maximum_seconds=max(t['seconds'] for t in owned),tests=owned),indent=2)+'\n')
(folder/'all-test-events.json').write_text(json.dumps(alltests,indent=2)+'\n')
changes=json.loads((folder/'counts-changes.json').read_text());statuses=json.loads((folder/'a-check-statuses.json').read_text());status_counts=collections.Counter(r['status'] for r in statuses)
skipped=[t for t in alltests if t['action']=='skip'];passed=[t for t in alltests if t['action']=='pass'];assert not [t for t in alltests if t['action']=='fail']
lines=['Re-cut hidden boundaries and a-check headers onto current fetched main, preserving both merge intents.',f'Branch compiler/loom-r-hidden-boundaries-ac-m; base {base}; original tip {oldtip}.','All requested recursive package suites, explicit reader guard, vet and gofmt pass functionally after the documented cache setup correction.','All 42 original compiler/flow mutants, both a-check header mutants, the old-generator parser mutant and the removed-wait mutant are caught.','Qualification: untouched TestSplitTSGoAgreesUnit00 cold product setup took 207.04 seconds; it was not rerun. No runtime C or header changes.','','## Base, application and conflict resolutions','',f'Fetched origin at the start and used its newest main, {base}, rather than the older 5179838b named in the request. Created compiler/loom-r-hidden-boundaries-ac-m from that commit. Used git merge-tree --write-tree --merge-base={oldtip}~1 origin/main {oldtip}, then git cherry-pick --no-commit {oldtip}. Only the source commit\'s own delta is applied. merge-tree.log and apply.log retain the observations.','', '- cloud/fast-gate/product-order.json: the conflict was main\'s newly added moves waits versus this change\'s canonical-closures wait. Kept every one of main\'s 422 wait keys and their exact values, and appended only cmd/adamic TestProduct_CommandRuntimeCanonicalClosures -> internal/oracle TestProduct_NativeRuntimesSanitized2. The canonical set remains at index 2 and Build uses index modulo 3, so this owner is still correct.', '- internal/oracle/counts.md: discarded the conflicted table, restored main\'s exact file, then regenerated it with the house Linux clang 20.1.8. No row was merged or edited manually. The generated 42 row deltas exactly equal the original change\'s rows; main\'s other rows and newer header remain intact.','', 'One additional integration edit is necessary: main\'s cloud/fast-gate/command-runtime-order.py only accepted nil feature lists and refused the new explicit []string canonical-closures declaration. Extended that parser to accept either nil or a literal []string list. This extends main\'s generator; it does not revert its behavior or remove any entry. The old parser exits 1 before writing; the extended parser exits 0 and is byte-for-byte idempotent on the resolved JSON. order-generator-mutant.json records the old-parser mutant. No other main line was deliberately reverted outside the original source delta.','','## Assumptions and limitations','', 'Interpreted the source branch as the exact supplied one-commit tip, not a diff from new main. Retained its existing TypeScript control pairs and historical evidence unchanged. Treated opt-in and platform skips as skips, not coverage. The later request for complete recursive package testing took precedence over the earlier 30-minute first-push target; the first pushed commit includes the completed evidence rather than an incomplete claim.', '', 'The blanket 60-second cold-run requirement is not fully met: the untouched existing native TestSplitTSGoAgreesUnit00 took 207.04 seconds. In the full build-mode invocation this nonparallel consumer ran before its parallel product builders; the checker archive alone took 156.37 seconds. Main already declares TestProduct_TSGoArchive, TestProduct_SplitTSGoSource and TestProduct_SplitTSGoBaseline. The cause is the cold product preparation inside this developer-mode run, not a new source test. It was not rerun or hidden by removing coverage. cold-native-budget.json retains the setup phases. A separate Loom-style, products-first measurement of this consumer was not run. All test events in all Go test files added or modified by the original change were below 60 seconds, maximum '+str(max(t['seconds'] for t in owned))+' seconds; touched-test-grain.json records that superset. This distinction does not erase the observed full-run budget breach.','','## Toolchain and recovered setup failures','', 'Ran export GOPROXY=\'https://proxy.golang.org|direct\', timeout 600 bash cloud/setup.sh and sourced /workspace/adamic-tools/env.sh. Setup passed. nproc=5, cgroup quota=4 CPUs, Go 1.27.1, Node v24.19.0, clang 20.1.8. Tests used GOMAXPROCS=4, ADAMIC_GOCACHE_STORE=off and TZ=UTC. Cumulative setup timings:','','```']
